import React from "react";
import { apiFetch } from "./api";
import { formatGhc } from "./money";
import { h } from "./h";

/**
 * @param {string | null | undefined} accessToken
 * @param {{ type: string, productId?: string, meta?: Record<string, unknown> }} payload
 */
export function trackVendorAnalyticsEvent(accessToken, payload) {
  if (!accessToken || !payload?.type) return;
  void apiFetch("/api/vendor/analytics/events", {
    method: "POST",
    headers: { Authorization: `Bearer ${accessToken}` },
    json: payload
  }).catch(() => {});
}

/** @param {{ x: number, y: number }[]} pts */
function smoothAreaPath(pts, baselineY) {
  if (pts.length === 0) return "";
  if (pts.length === 1) {
    const p = pts[0];
    return `M ${p.x} ${baselineY} L ${p.x} ${p.y} L ${p.x} ${baselineY} Z`;
  }
  let top = `M ${pts[0].x} ${pts[0].y}`;
  for (let i = 0; i < pts.length - 1; i++) {
    const p0 = pts[i];
    const p1 = pts[i + 1];
    const cx = (p0.x + p1.x) / 2;
    const cy = (p0.y + p1.y) / 2;
    top += ` Q ${p0.x} ${p0.y} ${cx} ${cy}`;
  }
  const last = pts[pts.length - 1];
  top += ` L ${last.x} ${last.y}`;
  return `${top} L ${last.x} ${baselineY} L ${pts[0].x} ${baselineY} Z`;
}

function smoothLinePath(pts) {
  if (pts.length === 0) return "";
  if (pts.length === 1) return `M ${pts[0].x} ${pts[0].y}`;
  let d = `M ${pts[0].x} ${pts[0].y}`;
  for (let i = 0; i < pts.length - 1; i++) {
    const p0 = pts[i];
    const p1 = pts[i + 1];
    const cx = (p0.x + p1.x) / 2;
    const cy = (p0.y + p1.y) / 2;
    d += ` Q ${p0.x} ${p0.y} ${cx} ${cy}`;
  }
  const last = pts[pts.length - 1];
  d += ` L ${last.x} ${last.y}`;
  return d;
}

function hexPoints(cx, cy, r) {
  const out = [];
  for (let i = 0; i < 6; i++) {
    const a = (Math.PI / 3) * i - Math.PI / 6;
    out.push(`${cx + r * Math.cos(a)},${cy + r * Math.sin(a)}`);
  }
  return out.join(" ");
}

/**
 * Aurora ribbon: smooth area, glow, mirrored reflection, hex markers — not a stock line chart.
 * @param {{ daily: Array<{ date: string; revenue: number }> }} props
 */
export function VendorRevenueLineChart({ daily }) {
  const w = 560;
  const svgH = 200;
  const padX = 32;
  const padB = 28;
  const padT = 20;
  const innerW = w - padX * 2;
  const baselineY = svgH - padB;
  const innerH = baselineY - padT;
  const vals = (daily || []).map((d) => Number(d.revenue) || 0);
  const max = Math.max(...vals, 1);
  const n = Math.max((daily || []).length, 1);
  const step = n > 1 ? innerW / (n - 1) : 0;
  const pts = (daily || []).map((d, i) => ({
    x: padX + i * step,
    y: padT + innerH * (1 - (Number(d.revenue) || 0) / max)
  }));
  const areaD = smoothAreaPath(pts, baselineY);
  const lineD = smoothLinePath(pts);
  const reflectTransform = `translate(0, ${baselineY * 2}) scale(1,-1)`;
  const tickStep = Math.max(1, Math.ceil(n / 6));

  return h("div", { className: "relative w-full overflow-hidden rounded-2xl" }, [
    h("div", {
      key: "cosmic-bg",
      className:
        "pointer-events-none absolute inset-0 bg-[radial-gradient(ellipse_at_20%_0%,rgba(56,189,248,0.25),transparent_50%),radial-gradient(ellipse_at_80%_100%,rgba(129,140,248,0.2),transparent_45%),linear-gradient(165deg,rgb(15_23_42)_0%,rgb(2_6_23)_55%,rgb(15_23_42)_100%)] dark:opacity-100"
    }),
    h("div", {
      key: "mesh",
      className:
        "pointer-events-none absolute inset-0 opacity-[0.12] dark:opacity-[0.18] [background-image:linear-gradient(rgba(148,163,184,0.4)_1px,transparent_1px),linear-gradient(90deg,rgba(148,163,184,0.35)_1px,transparent_1px)] [background-size:14px_14px]"
    }),
    h(
      "svg",
      {
        key: "svg",
        viewBox: `0 0 ${w} ${svgH}`,
        className: "relative z-[1] h-44 w-full max-w-full",
        role: "img",
        "aria-label": "Revenue ribbon by day",
        preserveAspectRatio: "xMidYMid meet"
      },
      [
        h("defs", { key: "defs" }, [
          h(
            "linearGradient",
            { key: "fillGrad", id: "auroraFill", x1: "0%", y1: "0%", x2: "0%", y2: "100%" },
            [
              h("stop", { offset: "0%", stopColor: "rgb(34 211 238)", stopOpacity: 0.55 }),
              h("stop", { offset: "55%", stopColor: "rgb(56 189 248)", stopOpacity: 0.2 }),
              h("stop", { offset: "100%", stopColor: "rgb(99 102 241)", stopOpacity: 0 })
            ]
          ),
          h(
            "linearGradient",
            { key: "strokeGrad", id: "auroraStroke", x1: "0%", y1: "0%", x2: "100%", y2: "0%" },
            [
              h("stop", { offset: "0%", stopColor: "rgb(125 211 252)" }),
              h("stop", { offset: "50%", stopColor: "rgb(56 189 248)" }),
              h("stop", { offset: "100%", stopColor: "rgb(165 180 252)" })
            ]
          ),
          h(
            "filter",
            { key: "glow", id: "ribbonGlow", x: "-25%", y: "-25%", width: "150%", height: "150%" },
            [
              h("feGaussianBlur", { key: "b", stdDeviation: "3", result: "ribbonBlur" }),
              h(
                "feMerge",
                { key: "m" },
                [
                  h("feMergeNode", { key: "m1", in: "ribbonBlur" }),
                  h("feMergeNode", { key: "m2", in: "SourceGraphic" })
                ]
              )
            ]
          )
        ]),
        h("line", {
          key: "base",
          x1: padX,
          x2: w - padX,
          y1: baselineY,
          y2: baselineY,
          stroke: "rgba(148,163,184,0.25)",
          strokeWidth: 1
        }),
        h("g", { key: "reflect", transform: reflectTransform, opacity: 0.14 }, [
          h("path", {
            d: areaD,
            fill: "url(#auroraFill)",
            stroke: "none"
          })
        ]),
        h("path", {
          key: "area",
          d: areaD,
          fill: "url(#auroraFill)",
          stroke: "none"
        }),
        h("path", {
          key: "lineGlow",
          d: lineD,
          fill: "none",
          stroke: "rgb(56 189 248)",
          strokeWidth: 5,
          strokeLinecap: "round",
          strokeLinejoin: "round",
          opacity: 0.35,
          filter: "url(#ribbonGlow)"
        }),
        h("path", {
          key: "line",
          d: lineD,
          fill: "none",
          stroke: "url(#auroraStroke)",
          strokeWidth: 2.2,
          strokeLinecap: "round",
          strokeLinejoin: "round"
        }),
        ...(daily || []).map((d, i) => {
          const p = pts[i];
          if (!p) return null;
          return h(
            "g",
            { key: `n-${d.date}` },
            [
              h("title", { key: "tt" }, `${d.date}: ${formatGhc(Number(d.revenue) || 0)}`),
              h("polygon", {
                key: "hex",
                points: hexPoints(p.x, p.y, 5),
                fill: "rgb(15 23 42)",
                stroke: "rgb(186 230 253)",
                strokeWidth: 1.2,
                opacity: 0.95
              }),
              (i % tickStep === 0 || i === n - 1) &&
                h(
                  "text",
                  {
                    key: "lb",
                    x: p.x,
                    y: svgH - 6,
                    fontSize: 9,
                    fill: "rgb(148 163 184)",
                    textAnchor: "middle",
                    className: "font-mono"
                  },
                  d.date.slice(5)
                )
            ].filter(Boolean)
          );
        })
      ]
    ),
    h(
      "p",
      {
        key: "cap",
        className:
          "relative z-[1] px-3 pb-2 text-center text-[10px] font-medium uppercase tracking-[0.2em] text-sky-200/80 dark:text-sky-300/90"
      },
      "Revenue stream · UTC"
    )
  ]);
}

const HIST_COLORS = [
  "from-sky-500/90 to-cyan-400/70",
  "from-violet-500/85 to-indigo-400/65",
  "from-emerald-500/85 to-teal-400/65",
  "from-amber-500/80 to-orange-400/60",
  "from-rose-500/80 to-pink-400/65",
  "from-slate-500/75 to-slate-400/55",
  "from-cyan-500/75 to-blue-500/60"
];

/**
 * Horizontal histogram: one bar per product (or “Other”). Bar length = share of your best-selling product’s revenue.
 * Data is all-time proceeds per product from analytics `topProducts` (same source as before).
 * @param {{ topProducts: Array<{ productId: string; name: string; revenue: number }> }} props
 */
export function VendorRevenueSnapshotHistogram({ topProducts }) {
  const rows = (topProducts || []).filter((p) => Number(p.revenue) > 0);
  const maxBars = 8;
  if (rows.length === 0) {
    return h("p", { className: "py-8 text-center text-sm text-slate-500 dark:text-slate-400" }, "No sales data yet.");
  }
  const sorted = [...rows].sort((a, b) => Number(b.revenue) - Number(a.revenue));
  const head = sorted.slice(0, maxBars);
  const tail = sorted.slice(maxBars);
  const otherRev = tail.reduce((s, p) => s + Number(p.revenue), 0);
  const slices = head.map((p) => ({ name: p.name, revenue: Number(p.revenue) }));
  if (otherRev > 0) slices.push({ name: "Other products", revenue: otherRev });

  const maxVal = Math.max(...slices.map((s) => s.revenue), 1);

  return h("div", { className: "space-y-3", role: "img", "aria-label": "Revenue histogram by product" }, [
    ...slices.map((s, i) => {
      const pct = Math.round((s.revenue / maxVal) * 100);
      const grad = HIST_COLORS[i % HIST_COLORS.length];
      return h(
        "div",
        { key: `${s.name}-${i}`, className: "group flex min-h-[2.25rem] items-stretch gap-2 sm:gap-3" },
        [
          h(
            "span",
            {
              className:
                "w-[28%] max-w-[9rem] shrink-0 truncate pt-1 text-left text-[11px] font-medium leading-tight text-slate-700 dark:text-slate-200 sm:w-32 sm:text-xs",
              title: s.name
            },
            s.name
          ),
          h(
            "div",
            {
              className:
                "relative min-w-0 flex-1 overflow-hidden rounded-lg border border-white/10 bg-slate-200/40 dark:bg-night-900/60",
              title: `${s.name}: ${formatGhc(s.revenue)} (${pct}% of top product)`
            },
            h("div", {
              className: `h-7 rounded-md bg-gradient-to-r ${grad} shadow-sm transition-[width] duration-300 ease-out sm:h-8`,
              style: { width: `${pct}%` }
            })
          ),
          h(
            "span",
            {
              className:
                "w-[4.5rem] shrink-0 pt-1 text-right font-mono text-[10px] text-slate-600 dark:text-slate-300 sm:w-24 sm:text-xs"
            },
            formatGhc(s.revenue)
          )
        ]
      );
    }),
    h(
      "p",
      {
        key: "note",
        className: "border-t border-white/10 pt-2.5 text-[10px] text-slate-500 dark:border-white/5 dark:text-slate-400"
      },
      "Longest bar = your #1 product (100%). Amounts on the right match the bar."
    )
  ]);
}
